            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Şu kavga bir bitse dersin, Acıkmasam dersin, Yorulmasam dersin; Çişim gelmese dersin, Uykum gelmese dersin; Ölsem desene!", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Ağlasam sesimi duyar mısınız? Mıralarımda; Dokunabilir misiniz? Gözyaşlarıma, ellerinizle?", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Bilmezdim şarkıların bu kadar güzel, Kelimelerinse kifayetsiz olduğunu Bu derde düşmeden önce.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Bir yer var, biliyorum; Her şeyi söylemek mümkün; Epiyce yaklaşmışım, duyuyorum; Anlatamıyorum.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Her gün bu kadar güzel mi bu deniz? Böyle mi görünür gökyüzü her zaman? Her zaman güzel mi bu kadar, Bu eşya, bu pencere? Değil, Vallahi değil; Bir iş var bu işin içinde.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Dağ başındasın; Derdin günün hasretlik; Akşam olmuş, Güneş batmış, İçmeyipte ne halt edecekdin?", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Sarhoş oldum da Seni hatırladım yine; Sol elim, Acemi elim, zavallı elim!", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Ne kadar severim o insanları! O insanlar ki, renkli, silik Dünyasında çıkartmaların Tavuklar, tavşanlar ve köpeklerle beraber Yaşayan insanlara benzer.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Baka kalırım giden geminin ardından; Atamam kendimi denize, dünya güzel; Serde erkeklik var, ağlayamam.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Gün doğmadan, Deniz daha bembeyazken çıkacaksın yola. Kürekleri tutmanın şehveti avuçlarında, İçinde bir iş görmenin saadeti, Gideceksin Gideceksin ırıpların çalkantısında.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Heeey Ne duruyorsun be, at kendini denize: Geride bekliyenin varmış, aldırma; Görmüyor musun, Her yanda hürriyet; Yelken ol, kürek ol, dümen ol, balık ol, su ol; Git gidebildiğin yere...", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Neler yapmadık şu vatan için! Kimimiz öldük; Kimimiz nutuk söyledik.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Eski bir sevdadan kurtulmuşum; Artık bütün kadınlar güzel; Gömleğim yeni, Yıkanmışım, Tıraş olmuşum; Sulh olmuş. Bahar gelmiş. Güneş açmış.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Sokağa çıkmışım, insanlar rahat; Ben de rahatım.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Beni bu güzel havalar mahvetti, Böyle havada istifa ettim Evkaftaki memuriyetimden. Tütüne böyle havada alıştım, Böyle havada aşık oldum.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Eve ekmekle tuz götürmeyi Böyle havalarda unuttum; Şiir yazma hastalığım Hep böyle havalarda nüksetti; Beni bu güzel havalar mahvetti.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Tüyden hafif olurum böyle sabahları; Karşı damda bir güneş parçası, İçimde kuş cıvıltıları, şarkıları; Bağıra çağıra düşerim yollara; Döner döner durur başım havalarda.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Sanırım ki günler hep güzel gidecek; Her sabah böyle bahar; Ne iş güç gelir aklıma, ne yoksulluğum.", Author = "Orhan Veli Kanık" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Orhan_Veli_Kanık", Text = "Derim ki: \"Sıkıntılar duradursun!\" Şairliğimle yetinir, Avunurum.", Author = "Orhan Veli Kanık" },
